#include <iostream>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <algorithm>
#include <queue>
#include <vector>
using namespace std;
const int INF = 10000000;
const int N = 210;
const int M = 21000;

struct Edge {
    int to, cap, rev;
};

vector<Edge> G[M];
int level[M], iter[M];

void add_edge(int from, int to, int cap) {
    G[from].push_back({to, cap, (int)G[to].size()});
    G[to].push_back({from, 0, (int)G[from].size()-1});
}

int S, T;

void bfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto &e : G[v]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < (int)G[v].size(); i++) {
        Edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
}

char grid1[12][12], grid2[12][12];
int sci[12][12], cap[12][12];
int stone[62][12][12];
int dp[62][12][12][12][12];
int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int n, t;

void expand() {
    for (int k = 1; k <= t; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (stone[k-1][i][j] == 1) {
                    stone[k][i][j] = 1;
                } else if (stone[k-1][i][j] == 2) {
                    stone[k][i][j] = 2;
                } else {
                    bool has2 = false;
                    for (int z = 0; z < 4; ++z) {
                        int nx = i + dir[z][0];
                        int ny = j + dir[z][1];
                        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
