                                break;
                            }
                        }
                    }
                    if (has2) stone[k][i][j] = 2;
                }
            }
        }
    }
}

int vis[12][12];
void dfs(int sx, int sy, int cx, int cy, int k) {
    vis[cx][cy] = 1;
    dp[k][sx][sy][cx][cy] = 1;
    if (k >= t || stone[k][cx][cy]) return;
    for (int z = 0; z < 4; ++z) {
        int nx = cx + dir[z][0];
        int ny = cy + dir[z][1];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
            if (stone[k][nx][ny]) continue;
            dfs(sx, sy, nx, ny, k+1);
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid1[i]+1);
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') stone[0][i][j] = 2;
            else if (grid1[i][j] == 'Y') stone[0][i][j] = 1;
            else sci[i][j] = grid1[i][j] - '0';
        }
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid2[i]+1);
        for (int j = 1; j <= n; ++j) {
            if (grid2[i][j] >= '0' && grid2[i][j] <= '9')
                cap[i][j] = grid2[i][j] - '0';
        }
    }

    expand();
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sci[i][j]) {
                memset(vis, 0, sizeof(vis));
                dfs(i, j, i, j, 0);
            }
    for (int k = 1; k <= t; ++k)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int nx = 1; nx <= n; ++nx)
                    for (int ny = 1; ny <= n; ++ny)
                        dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];

    S = 0; T = n*n*2 + 1;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            add_edge(S, (i-1)*n + j, sci[i][j]);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            add_edge(n*n + (i-1)*n + j, T, cap[i][j]);
