import java.util.*;

public class Main {
    static final int INF = 10000000;
    static final int N = 210;
    static final int M = 21000;

    static class Edge {
        int to, cap, rev;
        Edge(int to, int cap, int rev) {
            this.to = to;
            this.cap = cap;
            this.rev = rev;
        }
    }

    static ArrayList<Edge>[] G;
    static int[] level, iter;
    static int S, T;

    static void add_edge(int from, int to, int cap) {
        G[from].add(new Edge(to, cap, G[to].size()));
        G[to].add(new Edge(from, 0, G[from].size() - 1));
    }

    static void bfs(int s) {
        Arrays.fill(level, -1);
        Queue<Integer> q = new LinkedList<>();
        level[s] = 0;
        q.add(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : G[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.add(e.to);
                }
            }
        }
    }

    static int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int i = iter[v]; i < G[v].size(); i++) {
            iter[v] = i;
            Edge e = G[v].get(i);
            if (e.cap > 0 && level[v] < level[e.to]) {
                int d = dfs(e.to, t, Math.min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to].get(e.rev).cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    static int max_flow(int s, int t) {
        int flow = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;
            Arrays.fill(iter, 0);
            int f;
            while ((f = dfs(s, t, INF)) > 0) {
                flow += f;
            }
        }
    }

    static char[][] grid1 = new char[12][12];
    static char[][] grid2 = new char[12][12];
    static int[][] sci = new int[12][12];
    static int[][] cap = new int[12][12];
    static int[][][] stone = new int[62][12][12];
    static int[][][][][] dp = new int[62][12][12][12][12];
    static int[][] dir = {{-1,0},{1,0},{0,-1},{0,1}};
    static int n, t;
    static boolean[][] vis = new boolean[12][12];

    static void expand() {
        for (int k = 1; k <= t; ++k) {
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    if (stone[k-1][i][j] == 1) {
                        stone[k][i][j] = 1;
                    } else if (stone[k-1][i][j] == 2) {
                        stone[k][i][j] = 2;
                    } else {
                        boolean has2 = false;
                        for (int z = 0; z < 4; ++z) {
                            int nx = i + dir[z][0];
                            int ny = j + dir[z][1];
                            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                                if (stone[k-1][nx][ny] == 2) {
                                    has2 = true;
                                    break;
                                }
                            }
                        }
                        if (has2) stone[k][i][j] = 2;
                    }
                }
            }
        }
    }

    static void dfs(int sx, int sy, int cx, int cy, int k) {
        vis[cx][cy] = true;
        dp[k][sx][sy][cx][cy] = 1;
        if (k >= t || stone[k][cx][cy] != 0) return;
        for (int z = 0; z < 4; ++z) {
            int nx = cx + dir[z][0];
            int ny = cy + dir[z][1];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
                if (stone[k][nx][ny] != 0) continue;
                dfs(sx, sy, nx, ny, k+1);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine(); // consume newline

        for (int i = 1; i <= n; ++i) {
            String line = sc.next();
            for (int j = 1; j <= n; ++j) {
                grid1[i][j] = line.charAt(j-1);
                if (grid1[i][j] == 'Z') stone[0][i][j] = 2;
                else if (grid1[i][j] == 'Y') stone[0][i][j] = 1;
                else sci[i][j] = grid1[i][j] - '0';
            }
        }

        for (int i = 1; i <= n; ++i) {
            String line = sc.next();
            for (int j = 1; j <= n; ++j) {
                grid2[i][j] = line.charAt(j-1);
                if (grid2[i][j] >= '0' && grid2[i][j] <= '9')
                    cap[i][j] = grid2[i][j] - '0';
            }
        }

        expand();

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (sci[i][j] != 0) {
                    for (int a = 1; a <= n; ++a) Arrays.fill(vis[a], false);
                    dfs(i, j, i, j, 0);
                }
            }
        }

        for (int k = 1; k <= t; ++k) {
            for (int x = 1; x <= n; ++x) {
                for (int y = 1; y <= n; ++y) {
                    for (int nx = 1; nx <= n; ++nx) {
                        for (int ny = 1; ny <= n; ++ny) {
                            dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                        }
                    }
                }
            }
        }

        int totalNodes = n * n * 2 + 2;
        G = new ArrayList[totalNodes];
        for (int i = 0; i < totalNodes; ++i) G[i] = new ArrayList<>();
        level = new int[totalNodes];
        iter = new int[totalNodes];

        S = 0;
        T = n * n * 2 + 1;

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                int id = (i-1) * n + j;
                add_edge(S, id, sci[i][j]);
            }
        }

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                int id = (i-1) * n + j;
                add_edge(n * n + id, T, cap[i][j]);
            }
        }

        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int nx = 1; nx <= n; ++nx) {
                    for (int ny = 1; ny <= n; ++ny) {
                        if (sci[x][y] != 0 && cap[nx][ny] != 0) {
                            if (dp[t][x][y][nx][ny] != 0) {
                                int from = (x-1) * n + y;
                                int to = n * n + (nx-1) * n + ny;
                                add_edge(from, to, INF);
                            }
                        }
                    }
                }
            }
        }

        int ans = max_flow(S, T);
        System.out.println(ans);
        sc.close();
    }
}
